    <p>Create a 6-digit PIN to access Cash In.</p>
    <div class="dhf-pin-grid" id="wallet-pin-grid" role="group" aria-label="Enter a six-digit wallet PIN">
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" autocomplete="one-time-code" aria-label="PIN digit 1" required>
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" aria-label="PIN digit 2" required>
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" aria-label="PIN digit 3" required>
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" aria-label="PIN digit 4" required>
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" aria-label="PIN digit 5" required>
      <input class="dhf-pin-cell" type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" aria-label="PIN digit 6" required>
    </div>
    <p class="dhf-status" id="wallet-pin-error" role="alert" aria-live="polite"></p>
    <div class="dhf-actions"><button class="dhf-btn ghost" type="button" id="wallet-pin-cancel">Cancel</button><button class="dhf-btn" type="submit" id="wallet-pin-continue" disabled>Continue</button></div>
    <div class="dhf-modal-footnote">This PIN is not stored or verified by a server; it resets when the page reloads.</div>
  </form>
</div>
<div class="dhf-modal" id="cashin-modal" role="dialog" aria-modal="true" aria-labelledby="cashin-title">
  <div class="dhf-dialog dhf-cashin-dialog">
    <div class="dhf-cashin-header"><div class="dhf-cashin-symbol">â‚±</div><div><span class="dhf-step">DELIVERY HUB WALLET</span><h3 id="cashin-title">Cash In</h3><p>Select a verified rider remittance; a one-time code will be emailed to the hub manager.</p></div></div>
    <div class="dhf-cashin-balance"><span>Current Wallet Balance</span><strong id="cashin-current-balance">â‚±0.00</strong></div>
    <label class="dhf-field dhf-amount-field" for="cashin-remittance">Verified rider remittance<select id="cashin-remittance" class="dhf-field" style="margin-top:7px;width:100%;height:44px;border:1px solid #e4d8d4;border-radius:9px;padding:0 10px;background:white"></select></label>
    <p class="dhf-status" id="cashin-email-status" role="status" aria-live="polite"></p>
    <div class="dhf-otp-actions"><button class="dhf-btn ghost" type="button" id="cashin-send-otp">Send code to hub manager email</button><button class="dhf-btn ghost" type="button" id="cashin-resend-otp" hidden>Resend code</button><span class="dhf-otp-cooldown" id="cashin-resend-timer" aria-live="polite"></span></div>
    <label class="dhf-field dhf-amount-field" id="cashin-otp-wrap" for="cashin-otp" hidden>6-digit email code<input id="cashin-otp" type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" aria-label="Six-digit email verification code" aria-describedby="cashin-email-status" placeholder="Enter 6 digits"></label>
    <div class="dhf-cashin-after"><span>Balance after Cash In</span><strong id="cashin-after-balance">â‚±0.00</strong></div>
    <p class="dhf-status" id="cashin-error" role="status" aria-live="polite"></p>
    <div class="dhf-actions"><button class="dhf-btn ghost" type="button" data-close>Cancel</button><button class="dhf-btn" type="button" id="cashin-confirm">Confirm Cash In</button></div>
    <div class="dhf-modal-footnote">Only a reviewed, exact-match remittance can be cashed in. The action is recorded in the hub wallet ledger.</div>
  </div>
</div>
<div class="dhf-modal" id="reject-modal" role="dialog" aria-modal="true" aria-labelledby="reject-title">
  <form class="dhf-dialog dhf-reject-dialog" id="reject-form">
    <span class="dhf-step">RIDER REMITTANCE REVIEW</span>
    <h3 id="reject-title">Reject remittance</h3>
    <p>Choose a reason so the rider knows why this remittance was declined.</p>
    <div class="dhf-reject-summary" id="reject-summary"></div>
    <label class="dhf-reject-field" for="reject-reason"><span>Reason for rejection <b aria-hidden="true">*</b></span>
      <select id="reject-reason" required>
        <option value="">Select a reason</option>
        <option value="amount_mismatch">Declared amount does not match counted cash</option>
        <option value="missing_cod_records">Missing or mismatched COD records</option>
        <option value="invalid_details">Invalid or incomplete remittance details</option>
        <option value="duplicate">Suspected duplicate remittance</option>
        <option value="other">Other</option>
      </select>
    </label>
    <label class="dhf-reject-field" id="reject-details-wrap" for="reject-details" hidden><span>Additional details <b aria-hidden="true">*</b></span>
      <textarea id="reject-details" maxlength="2000" placeholder="Describe the reason for rejection"></textarea>
    </label>
    <p class="dhf-status" id="reject-error" role="alert" aria-live="polite"></p>
    <div class="dhf-actions"><button class="dhf-btn ghost" type="button" data-close>Cancel</button><button class="dhf-btn" type="submit" id="reject-submit">Reject Remittance</button></div>
  </form>
</div>
<div class="dhf-modal" id="verify-modal" role="dialog" aria-modal="true" aria-labelledby="verify-title">
  <form class="dhf-dialog dhf-verify-dialog" id="verify-form">
    <span class="dhf-step">RIDER REMITTANCE REVIEW</span>
    <h3 id="verify-title">Count and verify cash</h3>
    <p>Enter the cash amount received from the rider. A mismatch will be recorded for recount.</p>
    <div class="dhf-verify-summary"><span>Rider</span><strong id="verify-rider">—</strong><span>Declared COD</span><strong id="verify-declared">₱0.00</strong></div>
    <label class="dhf-reject-field" for="verify-amount"><span>Counted cash amount</span>
      <input class="dhf-count-input" id="verify-amount" type="text" inputmode="decimal" autocomplete="off" maxlength="15" placeholder="0.00" required>
    </label>
    <p class="dhf-count-feedback" id="verify-feedback" aria-live="polite">Enter the total cash amount counted.</p>
    <p class="dhf-status" id="verify-error" role="alert" aria-live="polite"></p>
    <div class="dhf-actions"><button class="dhf-btn ghost" type="button" data-close>Cancel</button><button class="dhf-btn" type="submit" id="verify-submit">Verify Remittance</button></div>
  </form>
</div>
<script>
(()=>{const $=id=>document.getElementById(id),money=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}),api='/api/v1/delivery_hub';let state=null,selectedRemittance=null;
const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';
async function call(url,options={}){const response=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf,...(options.headers||{})},...options});let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.message||Object.values(body.errors||{}).flat().join(' ')||'Request failed.');return body.data??body}
const empty=(tbody,cols,msg)=>{const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=cols;td.textContent=msg;tr.append(td);tbody.append(tr)};
function badge(status){const b=document.createElement('span');b.className='dhf-badge '+(['cashed_in','distributed','verified'].includes(status)?'distributed':(['pending','discrepancy'].includes(status)?'pending':''));b.textContent=String(status||'unknown').replaceAll('_',' ');return b}
function renderRemittances(){const body=$('remittance-rows');body.replaceChildren();if(!state.remittances.length)empty(body,6,'No rider remittances are recorded for this hub.');state.remittances.forEach(r=>{const tr=document.createElement('tr');[new Date(r.created_at).toLocaleString(),r.rider,(r.method||'—')+(r.reference_number?' / '+r.reference_number:''),money(r.amount)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});const st=document.createElement('td');st.append(badge(r.status));tr.append(st);const action=document.createElement('td');if(['pending','discrepancy'].includes(r.status)){const verify=document.createElement('button');verify.type='button';verify.className='dhf-btn';verify.textContent='Count & Verify';verify.onclick=()=>review(r);action.append(verify);const reject=document.createElement('button');reject.type='button';reject.className='dhf-btn ghost';reject.style.marginLeft='6px';reject.textContent='Reject';reject.onclick=()=>review(r,true);action.append(reject)}else if(r.status==='verified'){const b=document.createElement('button');b.type='button';b.className='dhf-btn';b.textContent='Cash In';b.onclick=()=>openCashIn(r.id);action.append(b)}else if(r.status==='cashed_in'){const b=document.createElement('button');b.type='button';b.className='dhf-btn';b.textContent='Distribute';b.onclick=()=>distribute(r.id);action.append(b)}else action.textContent='—';tr.append(action);tr.dataset.ref=String(r.id);tr.onclick=e=>{if(e.target.closest('button'))return;selectedRemittance=r;preview(r)};body.append(tr)});const select=$('cashin-remittance');select.replaceChildren();const eligible=state.remittances.filter(r=>r.status==='verified');if(!eligible.length){const o=document.createElement('option');o.value='';o.textContent='No verified remittances available';select.append(o)}eligible.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent='#'+r.id+' · '+r.rider+' · '+money(r.amount);select.append(o)});$('cashin-confirm').disabled=!eligible.length;$('distribute-all').disabled=!state.remittances.some(r=>r.status==='cashed_in')}
function preview(r){$('preview-ref').textContent='Remittance #'+r.id;$('preview-seller').textContent=money(r.orders.reduce((n,o)=>n+o.seller_amount,0));$('preview-admin').textContent=money(r.orders.reduce((n,o)=>n+o.commission_amount,0));$('preview-logistics').textContent=money(r.orders.reduce((n,o)=>n+o.shipping_fee,0));$('preview-total').textContent=money(r.amount);$('action-message').textContent=r.orders.length+' linked COD order(s) · '+(r.status||'').replaceAll('_',' ');$('distribute-one').disabled=r.status!=='cashed_in'}
function renderTables(){const s=state.summary;$('today-label').textContent=new Date().toLocaleDateString('en-PH',{timeZone:'Asia/Manila'});$('today-count').textContent=s.today_orders;$('today-due').textContent=money(s.today_due);$('today-distributed').textContent=money(s.today_distributed);$('today-remaining').textContent=money(s.today_remaining);$('wallet-balance').textContent=money(s.wallet_balance);$('available-inline').textContent=money(s.wallet_balance);$('total-required').textContent=money(s.today_remaining);$('shortfall').textContent=money(Math.max(0,s.today_remaining-s.wallet_balance));$('queue-orders').textContent=s.awaiting_orders;$('queue-amount').textContent=money(s.today_remaining);const coverage=s.today_remaining?Math.min(100,Math.round(s.wallet_balance/s.today_remaining*100)):100;$('readiness-percent').textContent=coverage+'%';$('readiness-fill').style.width=coverage+'%';$('readiness-badge').textContent=s.today_remaining?'Cash required':'Up to date';
const query=$('today-search').textContent.trim().toLowerCase();const rows=state.today.filter(r=>((r.ref||'')+' '+(r.buyer||'')).toLowerCase().includes(query)),body=$('today-rows');body.replaceChildren();if(!rows.length)empty(body,5,'No COD distributions recorded today.');rows.forEach(r=>{const tr=document.createElement('tr');[new Date(r.time).toLocaleTimeString('en-PH',{timeZone:'Asia/Manila'}),r.ref||'—',r.buyer||'—',money(r.amount)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});const td=document.createElement('td');td.append(badge(r.status));tr.append(td);body.append(tr)});$('today-page-text').textContent=rows.length+' distributed order(s) today';$('today-pager').replaceChildren();
const history=state.history,hbody=$('history-rows');hbody.replaceChildren();if(!history.length)empty(hbody,5,'No distribution history matches this period.');history.forEach(r=>{const tr=document.createElement('tr');[new Date(r.distributed_at).toLocaleDateString('en-PH',{timeZone:'Asia/Manila'}),r.ref||'—',r.buyer||'—',money(r.amount)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});const td=document.createElement('td');td.append(badge(r.status));tr.append(td);hbody.append(tr)});$('history-count').textContent=history.length;$('history-total').textContent=money(history.reduce((n,r)=>n+r.amount,0));$('history-distributed').textContent=money(history.filter(r=>r.status!=='held').reduce((n,r)=>n+r.amount,0));$('history-page-text').textContent=history.length+' record(s)';$('history-pager').replaceChildren();}
async function load(){try{const params=new URLSearchParams();if($('history-from').value)params.set('from',$('history-from').value);if($('history-to').value)params.set('to',$('history-to').value);if($('history-search').textContent.trim())params.set('search',$('history-search').textContent.trim());state=await call(api+'/finance?'+params);renderRemittances();renderTables();if(selectedRemittance)preview(state.remittances.find(r=>r.id===selectedRemittance.id)||selectedRemittance)}catch(e){$('action-message').textContent=e.message;const body=$('remittance-rows');body.replaceChildren();empty(body,6,e.message)}}
async function review(r,reject=false){let actual=r.amount,notes='';if(!reject){const raw=window.prompt('Enter the counted cash amount (₱'+Number(r.amount).toFixed(2)+')');if(raw===null)return;actual=Number(raw);if(!Number.isFinite(actual)||actual<0||Math.round(actual*100)!==actual*100){alert('Enter a valid amount with up to two decimal places.');return}}else{notes=window.prompt('Reason for rejecting this remittance:')||'';if(!notes.trim())return}try{const result=await call(api+'/rider-remittances/'+r.id+'/review',{method:'PATCH',body:JSON.stringify({status:reject?'rejected':'verified',actual_amount:actual,review_notes:notes})});$('action-message').textContent=reject?'Remittance rejected.':result.status==='verified'?'Remittance verified.':('Discrepancy recorded: '+(result.review_notes||'recount required'));await load()}catch(e){alert(e.message)}}
function otpReady(){return /^[0-9]{6}$/.test($('cashin-otp').value)}
function setCashInStatus(element,message,type=''){element.textContent=message;element.className='dhf-status'+(type?' '+type:'')}
function openCashIn(id){$('cashin-remittance').value=String(id);$('cashin-current-balance').textContent=money(state.summary.wallet_balance);$('cashin-after-balance').textContent=money(state.summary.wallet_balance+Number(state.remittances.find(r=>r.id===Number(id))?.amount||0));setCashInStatus($('cashin-error'),'');setCashInStatus($('cashin-email-status'),'');$('cashin-otp').value='';$('cashin-otp-wrap').hidden=true;$('cashin-confirm').disabled=true;$('cashin-send-otp').disabled=false;document.querySelectorAll('.dhf-modal').forEach(x=>x.classList.remove('open'));$('cashin-modal').classList.add('open')}
async function requestCashInOtp(){const id=Number($('cashin-remittance').value);if(!id)return;const button=$('cashin-send-otp');button.disabled=true;setCashInStatus($('cashin-email-status'),'Sending verification code to the hub manager email…');setCashInStatus($('cashin-error'),'');try{const result=await call(api+'/rider-remittances/'+id+'/cash-in/otp',{method:'POST',body:'{}'});$('cashin-otp-wrap').hidden=false;$('cashin-otp').value='';$('cashin-confirm').disabled=true;setCashInStatus($('cashin-email-status'),(result.message||'Verification code sent to the hub manager email.')+' Code expires in 10 minutes.','success');$('cashin-otp').focus()}catch(e){setCashInStatus($('cashin-email-status'),e.message||'Could not send the verification code. Check the hub manager email and mail settings.','error');button.disabled=false}}
async function cashIn(id){const otp=$('cashin-otp').value;if(!otpReady()){setCashInStatus($('cashin-error'),'Enter the six-digit numeric code sent to the hub manager email.','error');return}const button=$('cashin-confirm');button.disabled=true;setCashInStatus($('cashin-error'),'Verifying code…');try{const result=await call(api+'/rider-remittances/'+id+'/cash-in',{method:'POST',body:JSON.stringify({otp_code:otp})});$('cashin-modal').classList.remove('open');$('action-message').textContent='Cash-in '+result.reference+' recorded for '+money(result.amount)+'.';await load()}catch(e){setCashInStatus($('cashin-error'),e.message||'Could not verify the code. Try again.','error');button.disabled=!otpReady()}}
async function distribute(id){try{const result=await call(api+'/rider-remittances/'+id+'/distribute',{method:'POST',body:'{}'});$('action-message').textContent=result.orders+' order(s) distributed: '+money(result.amount)+'.';await load()}catch(e){alert(e.message)}}
$('cashin-open').onclick=()=>{const id=Number($('cashin-remittance').value);if(!id){alert('There are no verified remittances ready for cash-in.');return}openCashIn(id)};$('cashin-send-otp').onclick=requestCashInOtp;$('cashin-confirm').onclick=async()=>{const id=Number($('cashin-remittance').value);if(id)await cashIn(id)};$('cashin-otp').addEventListener('input',event=>{const input=event.currentTarget;const digits=input.value.replace(/[^0-9]/g,'').slice(0,6);if(input.value!==digits)input.value=digits;$('cashin-confirm').disabled=!otpReady();if(digits.length===6)setCashInStatus($('cashin-error'),'')});$('cashin-remittance').onchange=()=>{const amount=Number(state.remittances.find(r=>r.id===Number($('cashin-remittance').value))?.amount||0);$('cashin-after-balance').textContent=money(state.summary.wallet_balance+amount);setCashInStatus($('cashin-email-status'),'');setCashInStatus($('cashin-error'),'');$('cashin-otp').value='';$('cashin-otp-wrap').hidden=true;$('cashin-confirm').disabled=true;$('cashin-send-otp').disabled=false};$('today-search').addEventListener('input',renderTables);$('distribute-one').onclick=()=>selectedRemittance?.status==='cashed_in'&&distribute(selectedRemittance.id);$('distribute-all').onclick=async()=>{for(const r of state.remittances.filter(x=>x.status==='cashed_in'))await distribute(r.id)};$('finance-refresh').onclick=load;
const otpRequested=new Set(),otpResendAt=new Map();let otpTimer=null;
function syncOtpButtons(){const id=Number($('cashin-remittance').value),sent=otpRequested.has(id),left=Math.max(0,Math.ceil(((otpResendAt.get(id)||0)-Date.now())/1000));$('cashin-send-otp').hidden=sent;$('cashin-resend-otp').hidden=!sent;$('cashin-resend-otp').disabled=left>0;$('cashin-resend-otp').textContent=left?'Resend code ('+left+'s)':'Resend code';$('cashin-resend-timer').textContent=left?'You can request another code when the timer ends.':'';$('cashin-otp-wrap').hidden=!sent;$('cashin-confirm').disabled=!sent||!otpReady()}
function startOtpCooldown(id,seconds=60){otpResendAt.set(id,Date.now()+seconds*1000);if(otpTimer)clearInterval(otpTimer);syncOtpButtons();otpTimer=setInterval(()=>{if(Number($('cashin-remittance').value)===id)syncOtpButtons();if(Date.now()>=(otpResendAt.get(id)||0)){clearInterval(otpTimer);otpTimer=null;syncOtpButtons()}},1000)}
const previewBeforeMargin=preview;preview=function(r){previewBeforeMargin(r);$('preview-margin').textContent=money(r.orders.reduce((n,o)=>n+Number(o.platform_shipping_margin||0),0))};
openCashIn=function(id){$('cashin-remittance').value=String(id);$('cashin-current-balance').textContent=money(state.summary.wallet_balance);$('cashin-after-balance').textContent=money(state.summary.wallet_balance+Number(state.remittances.find(r=>r.id===Number(id))?.amount||0));setCashInStatus($('cashin-error'),'');setCashInStatus($('cashin-email-status'),'');$('cashin-otp').value='';syncOtpButtons();document.querySelectorAll('.dhf-modal').forEach(x=>x.classList.remove('open'));$('cashin-modal').classList.add('open')};
requestCashInOtp=async function(resend=false){const id=Number($('cashin-remittance').value);if(!id)return;const button=$(resend?'cashin-resend-otp':'cashin-send-otp');button.disabled=true;setCashInStatus($('cashin-email-status'),resend?'Resending verification code to the hub manager email…':'Sending verification code to the hub manager email…');setCashInStatus($('cashin-error'),'');try{const result=await call(api+'/rider-remittances/'+id+'/cash-in/otp',{method:'POST',body:'{}'});otpRequested.add(id);$('cashin-otp').value='';setCashInStatus($('cashin-email-status'),(result.message||'Verification code sent to the hub manager email.')+' Code expires in 10 minutes.','success');startOtpCooldown(id,Number(result.resend_after_seconds||60));$('cashin-otp').focus()}catch(e){if((e.message||'').toLowerCase().includes('wait one minute')){otpRequested.add(id);startOtpCooldown(id,60)}else button.disabled=false;setCashInStatus($('cashin-email-status'),e.message||'Could not send the verification code. Check the hub manager email and mail settings.','error')}};
$('cashin-send-otp').onclick=()=>requestCashInOtp(false);$('cashin-resend-otp').onclick=()=>requestCashInOtp(true);$('cashin-remittance').onchange=()=>{const amount=Number(state.remittances.find(r=>r.id===Number($('cashin-remittance').value))?.amount||0);$('cashin-after-balance').textContent=money(state.summary.wallet_balance+amount);setCashInStatus($('cashin-email-status'),'');setCashInStatus($('cashin-error'),'');$('cashin-otp').value='';syncOtpButtons()};$('cashin-otp').addEventListener('input',()=>syncOtpButtons());
const reviewWithPrompt=review;let remittanceToReject=null;
review=function(r,reject=false){if(!reject)return reviewWithPrompt(r,false);remittanceToReject=r;$('reject-summary').replaceChildren();const rider=document.createElement('strong');rider.textContent=r.rider+' · '+money(r.amount);$('reject-summary').append(rider);const submitted=document.createElement('span');submitted.textContent='Submitted '+new Date(r.created_at).toLocaleString();$('reject-summary').append(submitted);$('reject-reason').value='';$('reject-details').value='';$('reject-details-wrap').hidden=true;$('reject-details').required=false;setCashInStatus($('reject-error'),'');$('reject-modal').classList.add('open');$('reject-reason').focus()};
$('reject-reason').addEventListener('change',()=>{const other=$('reject-reason').value==='other';$('reject-details-wrap').hidden=!other;$('reject-details').required=other;if(!other)$('reject-details').value='';setCashInStatus($('reject-error'),'')});
$('reject-form').addEventListener('submit',async event=>{event.preventDefault();if(!remittanceToReject)return;const reason=$('reject-reason').value,details=$('reject-details').value.trim();if(!reason){setCashInStatus($('reject-error'),'Select a reason for rejecting this remittance.','error');return}if(reason==='other'&&!details){setCashInStatus($('reject-error'),'Add details when you select Other.','error');$('reject-details').focus();return}const button=$('reject-submit');button.disabled=true;setCashInStatus($('reject-error'),'Saving rejection…');try{await call(api+'/rider-remittances/'+remittanceToReject.id+'/review',{method:'PATCH',body:JSON.stringify({status:'rejected',rejection_reason:reason,review_notes:reason==='other'?details:null})});$('reject-modal').classList.remove('open');$('action-message').textContent='Remittance rejected. Reason: '+(reason==='other'?details:$('reject-reason').selectedOptions[0].textContent);remittanceToReject=null;await load()}catch(e){setCashInStatus($('reject-error'),e.message||'Could not reject this remittance.','error')}finally{button.disabled=false}});
const reviewWithDialogs=review;let remittanceToVerify=null;
review=function(r,reject=false){if(reject)return reviewWithDialogs(r,true);remittanceToVerify=r;$('verify-rider').textContent=r.rider;$('verify-declared').textContent=money(r.amount);$('verify-amount').value='';$('verify-amount').dataset.declared=String(Number(r.amount));$('verify-feedback').textContent='Enter the total cash amount counted.';$('verify-feedback').className='dhf-count-feedback';setCashInStatus($('verify-error'),'');$('verify-modal').classList.add('open');$('verify-amount').focus()};
$('verify-amount').addEventListener('input',event=>{const input=event.currentTarget;let value=input.value.replace(/[^0-9.]/g,'');const dot=value.indexOf('.');if(dot!==-1)value=value.slice(0,dot+1)+value.slice(dot+1).replace(/\./g,'').slice(0,2);if(input.value!==value)input.value=value;const feedback=$('verify-feedback');if(!value||value==='.') {feedback.textContent='Enter the total cash amount counted.';feedback.className='dhf-count-feedback';return}if(!/^\d+(\.\d{1,2})?$/.test(value)){feedback.textContent='Use digits and up to two decimal places.';feedback.className='dhf-count-feedback mismatch';return}const difference=Math.round((Number(value)-Number(input.dataset.declared||0))*100)/100;if(Math.abs(difference)<0.01){feedback.textContent='Count matches the declared COD amount.';feedback.className='dhf-count-feedback match'}else{feedback.textContent='Count differs by '+money(Math.abs(difference))+'; this remittance will be flagged for recount.';feedback.className='dhf-count-feedback mismatch'}});
$('verify-form').addEventListener('submit',async event=>{event.preventDefault();if(!remittanceToVerify)return;const value=$('verify-amount').value.trim();if(!/^\d+(\.\d{1,2})?$/.test(value)){setCashInStatus($('verify-error'),'Enter a valid amount with no more than two decimal places.','error');$('verify-amount').focus();return}const button=$('verify-submit');button.disabled=true;setCashInStatus($('verify-error'),'Saving counted amount…');try{const result=await call(api+'/rider-remittances/'+remittanceToVerify.id+'/review',{method:'PATCH',body:JSON.stringify({status:'verified',actual_amount:Number(value).toFixed(2)})});$('verify-modal').classList.remove('open');$('action-message').textContent=result.status==='verified'?'Remittance verified and ready for cash-in.':'Cash discrepancy recorded. Recount required.';remittanceToVerify=null;await load()}catch(e){setCashInStatus($('verify-error'),e.message||'Could not save the counted amount.','error')}finally{button.disabled=false}});
const loadBeforeRemittancePolish=load;
load=async function(){await loadBeforeRemittancePolish();if(!state)return;document.querySelectorAll('#remittance-rows tr[data-ref]').forEach(row=>{const remittance=state.remittances.find(item=>String(item.id)===row.dataset.ref);if(!remittance)return;const methodCell=row.cells[2];if(methodCell){const parts=methodCell.textContent.split(' / '),method=(parts.shift()||'').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());methodCell.replaceChildren();const label=document.createElement('span');label.className='dhf-method';label.textContent=method;methodCell.append(label);if(parts.length){const reference=document.createElement('small');reference.className='dhf-reference';reference.textContent='Reference: '+parts.join(' / ');methodCell.append(reference)}}if(['verified','cashed_in'].includes(remittance.status)&&row.cells[5])row.cells[5].replaceChildren()})};
let walletPinReady=false,pendingPinRemittanceId=null;
const openCashInWithoutPin=openCashIn;
openCashIn=function(id){if(walletPinReady){openCashInWithoutPin(id);return}pendingPinRemittanceId=id;const cells=[...document.querySelectorAll('#wallet-pin-grid .dhf-pin-cell')];cells.forEach(cell=>cell.value='');$('wallet-pin-continue').disabled=true;setCashInStatus($('wallet-pin-error'),'');$('wallet-pin-modal').classList.add('open');cells[0]?.focus()};
const walletPinCells=[...document.querySelectorAll('#wallet-pin-grid .dhf-pin-cell')];
function syncWalletPin(){const complete=walletPinCells.every(cell=>/^[0-9]$/.test(cell.value));$('wallet-pin-continue').disabled=!complete;return complete}
walletPinCells.forEach((cell,index)=>{cell.addEventListener('input',event=>{const digits=event.currentTarget.value.replace(/[^0-9]/g,'');event.currentTarget.value=digits.slice(-1);setCashInStatus($('wallet-pin-error'),'');if(event.currentTarget.value&&index<walletPinCells.length-1)walletPinCells[index+1].focus();syncWalletPin()});cell.addEventListener('keydown',event=>{if(event.key==='Backspace'&&!cell.value&&index>0){walletPinCells[index-1].value='';walletPinCells[index-1].focus();syncWalletPin()}if(event.key==='ArrowLeft'&&index>0)walletPinCells[index-1].focus();if(event.key==='ArrowRight'&&index<walletPinCells.length-1)walletPinCells[index+1].focus()});cell.addEventListener('paste',event=>{const value=event.clipboardData?.getData('text')||'';const digits=value.replace(/[^0-9]/g,'').slice(0,6);if(!digits)return;event.preventDefault();digits.split('').forEach((digit,position)=>{if(walletPinCells[position])walletPinCells[position].value=digit});walletPinCells[Math.min(digits.length,walletPinCells.length)-1]?.focus();syncWalletPin()})});
$('wallet-pin-form').addEventListener('submit',event=>{event.preventDefault();if(!syncWalletPin()){setCashInStatus($('wallet-pin-error'),'Enter all six digits to continue.','error');return}walletPinReady=true;walletPinCells.forEach(cell=>cell.value='');$('wallet-pin-modal').classList.remove('open');if(pendingPinRemittanceId)openCashInWithoutPin(pendingPinRemittanceId);pendingPinRemittanceId=null});
$('wallet-pin-cancel').onclick=()=>{$('wallet-pin-modal').classList.remove('open');walletPinCells.forEach(cell=>cell.value='');pendingPinRemittanceId=null;setCashInStatus($('wallet-pin-error'),'')};
const historySearch=$('history-search');['history-from','history-to'].forEach(id=>$(id).addEventListener('change',load));historySearch.textContent='';historySearch.addEventListener('input',()=>{clearTimeout(window.financeSearchTimer);window.financeSearchTimer=setTimeout(load,250)});$('history-reset').onclick=()=>{const d=new Date(),date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila'}).format(d);$('history-from').value=date.slice(0,7)+'-01';$('history-to').value=date;historySearch.textContent='';load()};$('history-from').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila'}).format(new Date()).slice(0,7)+'-01';$('history-to').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila'}).format(new Date());document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.dhf-modal').classList.remove('open'));document.querySelectorAll('.dhf-modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));load();})();
</script></body></html>
